fn advance_registry(birth:&mut SnapshotReadRegistryBirth,cx:&mut StepContext<'_>)->Result<(),OriginalTurnFailure>{let d=birth.demands()?;let g=cx.retained_grant();if !semio_framework_value::retained_clone::retained_clone_grant_admits(g,d){return Ok(())}let result=cx.with_native_receiving(|control|birth.advance(g,control));cx.consume_fuel(birth.last_turn_work());let p=result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());let reconciled=cx.receiving_issued_grant().ok_or_else(||invalid("native registry birth omitted its original receiving scope")).and_then(|issued|cx.consume_receiving_retained(issued,p));match(result,reconciled){(Ok(_),Ok(()))=>Ok(()),(Err(error),Ok(()))=>Err(error.into()),(Ok(_),Err(error))=>Err(error.into()),(Err(error),Err(receipt))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=Some(receipt);Err(failure)}}}

